import json, math, copy
from collections import defaultdict
from cost_model import CostModel, align, HEADS, HIDDEN

cm=CostModel(64)
C=cm.c
Kd_attn,Kd_mlp=C.Kd_attn,C.Kd_mlp
Kp_attn,Kp_mlp=C.Kp_attn,C.Kp_mlp
Td_attn,Td_mlp=C.Td_attn,C.Td_mlp
Tp_attn,Tp_mlp=C.Tp_attn,C.Tp_mlp
B=Kd_mlp*HIDDEN
B2=Td_mlp*HIDDEN

def load(b): return [json.loads(l) for l in open(f'../input_data/requests_bucket_{b}.jsonl')]

def fcost(S,G):
    ss=cm._sum_sq_arith(S,G); sl=G*S+G*(G-1)/2
    return Kd_attn*ss+B*sl
def flat(S,G):
    ss=cm._sum_sq_arith(S,G); sl=G*S+G*(G-1)/2
    return Td_attn*ss+B2*sl
def prefcost(S): return Kp_attn*S*S+Kp_mlp*S*HIDDEN
def preflat(S): return Tp_attn*S*S+Tp_mlp*S*HIDDEN

class Batch:
    __slots__=('S','G','n','sumg','ids','reqs')
    def __init__(self,S,G,rs):
        self.S=S; self.G=G; self.n=len(rs); self.sumg=sum(r['gen_len'] for r in rs)
        self.reqs=rs
    def cost(self): return self.n*fcost(self.S,self.G)
    def pad(self): return self.n*self.G-self.sumg
    def lat(self): return flat(self.S,self.G)
    def seq(self): return preflat(self.S)+self.lat()+8

def merge(a,b):
    assert a.S==b.S
    G=max(a.G,b.G)
    # b with higher G? any
    nb=Batch.__new__(Batch)
    nb.S=a.S; nb.G=G; nb.n=a.n+b.n; nb.sumg=a.sumg+b.sumg; nb.reqs=a.reqs+b.reqs
    return nb

def plan_metrics(reqs,batches):
    # one shape = max S over all
    Smaxshape=max(bt.S for bt in batches)
    shape={'seq_align':Smaxshape,'heads_align':HEADS,'hidden_align':HIDDEN}
    plan=[]; bid=0
    for bt in batches:
        bid+=1
        for r in bt.reqs:
            plan.append({'request_id':r['request_id'],'batch_id':f'b-{bid:04d}','shape':shape})
    return cm.plan_metrics({r['request_id']:r for r in reqs},plan)

def greedy(reqs, target_seq, mode='pad_ratio', stop_margin=0.98):
    # init by exact (S,G)
    d=defaultdict(list)
    for r in reqs:
        d[(align(r['prompt_len'],64),r['gen_len'])].append(r)
    batches=[Batch(S,G,rs) for (S,G),rs in d.items()]
    # group indices by S; maintain sorted by G
    def regroup(bs):
        by=defaultdict(list)
        for bt in bs: by[bt.S].append(bt)
        for S in by: by[S].sort(key=lambda b:b.G)
        return by
    by=regroup(batches)
    def total_seq(by): return sum(bt.seq() for S in by for bt in by[S])
    def total_pad(by): return sum(bt.pad() for S in by for bt in by[S])
    def total_cost(by): return sum(bt.cost() for S in by for bt in by[S])
    cur_seq=total_seq(by)
    step=0
    while cur_seq>target_seq:
        best=None
        for S,arr in by.items():
            for i in range(len(arr)-1):
                a,b=arr[i],arr[i+1]
                nb=merge(a,b)
                ds=cur_seq-(cur_seq-a.seq()-b.seq()+nb.seq()) # seq saving
                dc=nb.cost()-a.cost()-b.cost()-1e7  # minus saved overhead
                dp=nb.pad()-a.pad()-b.pad()
                if mode=='pad_ratio':
                    score=dp/max(ds,1)
                elif mode=='cost':
                    score=max(dc,0)/max(ds,1)
                elif mode=='mix':
                    score=(max(dc,0)+5e7*dp)/max(ds,1)
                elif mode=='padsave':
                    score=(dp+1)/max(ds,1)
                if best is None or score<best[0]:
                    best=(score,ds,dc,dp,S,i,nb)
        if best is None: break
        score,ds,dc,dp,S,i,nb=best
        arr=by[S]
        arr[i:i+2]=[nb]
        cur_seq-=ds
        step+=1
    return [bt for S in by for bt in by[S]]

def report(tag,reqs,batches):
    m=plan_metrics(reqs,batches)
    print(tag,'nb',len(batches),'cost %.4e pad %.4f p95 %.4e seq %.4e'%(m['cost'],m['pad_ratio'],m['p95_latency_ms'],m['sequential_timecost']))
    return m

if __name__=='__main__':
    limits={1:dict(cost=3.0e11,pad=0.055,p95=2.1e6,seq=2.7e8),2:dict(cost=4.8e10,pad=0.15,p95=2.1e5,seq=3.2e7)}
    for b in [1,2]:
        rs=load(b)
        print('=== bucket',b)
        for mode in ['pad_ratio','cost','mix','padsave']:
            batches=greedy(rs,limits[b]['seq']*0.97,mode)
            report(mode,rs,batches)
