#!/usr/bin/env python3
"""Shape-aware batching scheduler.

Requests are first coalesced into exact (seq_align, gen_len) batches, then
adjacent generation-length groups within each seq_align group are merged
greedily until the sequential-execution target is reached.  The plan uses a
single tensor shape per input file (the largest aligned prompt), which keeps
compilation cost and the number of unique shapes minimal.
"""

from __future__ import annotations

import json
import pathlib
import sys
from collections import defaultdict

SCRIPT_DIR = pathlib.Path(__file__).resolve().parent
if str(SCRIPT_DIR) not in sys.path:
    sys.path.insert(0, str(SCRIPT_DIR))

from cost_model import (  # noqa: E402
    HEADS,
    HIDDEN,
    CostModel,
    align,
)

ROOT = SCRIPT_DIR.parent
GRAN = 64
MAX_SHAPES = 8

# Sequential-time targets are set slightly below the required thresholds so
# that the greedy merge has safety margin on all metrics.
TARGET_SEQ_FRACTION = 0.90


def load_requests(path: pathlib.Path) -> list[dict]:
    with path.open() as f:
        return [json.loads(line) for line in f]


class _Batch:
    __slots__ = ("seq", "gen", "count", "sum_gen", "requests")

    def __init__(self, seq: int, gen: int, requests: list[dict]) -> None:
        self.seq = seq
        self.gen = gen
        self.count = len(requests)
        self.sum_gen = sum(r["gen_len"] for r in requests)
        self.requests = requests


class _Model:
    def __init__(self, consts) -> None:
        self.c = consts

    @staticmethod
    def _sum_sq(a: int, n: int) -> int:
        return n * a * a + a * n * (n - 1) + (n * (n - 1) * (2 * n - 1)) // 6

    @staticmethod
    def _sum_lin(a: int, n: int) -> float:
        return n * a + n * (n - 1) / 2

    def decode_cost(self, a: int, n: int) -> float:
        c = self.c
        return c.Kd_attn * self._sum_sq(a, n) + c.Kd_mlp * HIDDEN * self._sum_lin(a, n)

    def decode_lat(self, a: int, n: int) -> float:
        c = self.c
        return c.Td_attn * self._sum_sq(a, n) + c.Td_mlp * HIDDEN * self._sum_lin(a, n)

    def prefill_lat(self, a: int) -> float:
        c = self.c
        return c.Tp_attn * a * a + c.Tp_mlp * a * HIDDEN

    def batch_cost(self, b: _Batch) -> float:
        return b.count * self.decode_cost(b.seq, b.gen)

    def batch_pad(self, b: _Batch) -> int:
        return b.count * b.gen - b.sum_gen

    def batch_seq(self, b: _Batch) -> float:
        c = self.c
        return (
            self.prefill_lat(b.seq)
            + self.decode_lat(b.seq, b.gen)
            + c.Tbatch_overhead_ms
        )


def _merge(a: _Batch, b: _Batch) -> _Batch:
    merged = _Batch.__new__(_Batch)
    merged.seq = a.seq
    merged.gen = max(a.gen, b.gen)
    merged.count = a.count + b.count
    merged.sum_gen = a.sum_gen + b.sum_gen
    merged.requests = a.requests + b.requests
    return merged


def _greedy_batches(reqs: list[dict], model: _Model, target_seq: float) -> list[_Batch]:
    initial: defaultdict[tuple[int, int], list[dict]] = defaultdict(list)
    for r in reqs:
        initial[(align(r["prompt_len"], GRAN), r["gen_len"])].append(r)

    by_seq: defaultdict[int, list[_Batch]] = defaultdict(list)
    for (seq, gen), group in initial.items():
        by_seq[seq].append(_Batch(seq, gen, group))
    for seq in by_seq:
        by_seq[seq].sort(key=lambda b: b.gen)

    current_seq = sum(model.batch_seq(b) for arr in by_seq.values() for b in arr)

    while current_seq > target_seq:
        best = None
        for seq, arr in by_seq.items():
            for i in range(len(arr) - 1):
                a, b = arr[i], arr[i + 1]
                merged = _merge(a, b)
                seq_saved = (
                    model.batch_seq(a) + model.batch_seq(b) - model.batch_seq(merged)
                )
                pad_added = model.batch_pad(merged) - model.batch_pad(a) - model.batch_pad(b)
                score = pad_added / max(seq_saved, 1.0)
                if best is None or score < best[0]:
                    best = (score, seq, i, merged, seq_saved)
        if best is None:
            break
        _, seq, i, merged, seq_saved = best
        arr = by_seq[seq]
        arr[i : i + 2] = [merged]
        current_seq -= seq_saved

    return [b for seq in by_seq for b in by_seq[seq]]


def build_plan(reqs: list[dict], target_seq: float) -> list[dict]:
    model = _Model(CostModel(GRAN).c)
    batches = _greedy_batches(reqs, model, target_seq)

    seq_align = max(align(r["prompt_len"], GRAN) for r in reqs)
    shape = {
        "seq_align": seq_align,
        "heads_align": HEADS,
        "hidden_align": HIDDEN,
    }

    plan: list[dict] = []
    for bid, batch in enumerate(batches, start=1):
        batch_id = f"b-{bid:04d}"
        for r in batch.requests:
            plan.append(
                {
                    "request_id": r["request_id"],
                    "batch_id": batch_id,
                    "shape": dict(shape),
                }
            )
    return plan


def _write_plan(path: pathlib.Path, plan: list[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w") as f:
        for record in plan:
            f.write(json.dumps(record) + "\n")


def main() -> None:
    targets = {
        1: 2.7e8 * TARGET_SEQ_FRACTION,
        2: 3.2e7 * TARGET_SEQ_FRACTION,
    }
    for bucket, target in targets.items():
        reqs = load_requests(ROOT / "input_data" / f"requests_bucket_{bucket}.jsonl")
        plan = build_plan(reqs, target)
        _write_plan(ROOT / "output_data" / f"plan_b{bucket}.jsonl", plan)


if __name__ == "__main__":
    main()
